from usg.dsl import *

# Find a crossing with a signal
crossings = MAP.crossings(control="signals") or MAP.crossings()
if crossings:
    cr = crossings[0]
else:
    cr = MAP.crossings()[0]

cid, road, s = cr["id"], cr["road"], cr["road_s"]
length = MAP.road(road)["length"]

# Get the signal name for this crossing
signal_id = cr.get("signal_id")
signal_name = signal_id if signal_id else None

scenario = ScenarioBuilder("cross_with_bus", MAP, scenario_type="dyn_nav",
                           description="Cross a road while a bus approaches; avoid it.")
scenario.user(MAP.crossing_side(cid, "start", inset=2.0))

# Create the bus vehicle along the road, starting further away from the crossing
# Use a larger distance from the start of the road segment to ensure safety margin
route = MAP.drive_route(road, max(0.0, s - 50.0), min(length, s + 30.0), "forward")
scenario.vehicle("Bus1", route[0], route[1:], speed=10.0, model="bus_blue", start_when=when_user_within(20.0))

# Create a signal cycle if we have a signal
if signal_name:
    scenario.signal_cycle(cid, green=15, red=20, initial="red")

handles = scenario.apply_spec({
    "tasks": [{
        "name": "cross_with_bus",
        "instruction": "Check for the bus, then cross the road.",
        "goal": {
            "op": "call",
            "name": "cross",
            "args": {
                "far_zone": {
                    "kind": "crossing_side",
                    "id": "crossing_4",
                    "side": "end",
                    "inset": 1.0,
                    "r": 1.5
                }
            }
        },
        "safety": [{
            "op": "call",
            "name": "collision_free",
            "args": {
                "entity": "Bus1",
                "r": 0.3
            }
        }],
        "timeout": {
            "initial": 60,
            "baseline": 90
        }
    }]
})

