# Build a safe start point on the sidewalk leading to crossing_4
crossings = MAP.crossings()
if not crossings:
    raise Exception("No crossings found")
crossing = crossings[0]
road = MAP.road(crossing["road"])
side = MAP.side_of_road(crossing["center"])
start = MAP.sidewalk_at(road, side, 20.0)  # ~20m back on the sidewalk

# Adjust SPEC to match the actual distance and ensure safety
# The error indicates the 'stay_on' safety rule is conflicting with the goal.
# This often happens when the 'reach' goal zone is too small or the start is too far.
# We will use a larger radius for the goal and ensure the start is close enough.
SPEC = {
    "tasks": [{
        "name": "walk_sidewalk",
        "instruction": "Walk to the crossing using only the sidewalk.",
        "goal": {
            "op": "call",
            "name": "reach",
            "args": {
                "zone": {
                    "kind": "crossing",
                    "id": "crossing_4",
                    "r": 5
                }
            }
        },
        "safety": [
            {
                "op": "call",
                "name": "stay_on",
                "args": {
                    "surface": "sidewalk"
                }
            }
        ],
        "timeout": {
            "initial": 1200,
            "baseline": 1800
        }
    }]
}

scenario = ScenarioBuilder("scenario", MAP, scenario_type="custom")
scenario.user(start)
handles = scenario.apply_spec(SPEC)

